<?php
declare(strict_types=1);
namespace Moves\Services;
use DateTimeImmutable;use InvalidArgumentException;use MovesCode\Model\Connection;use PDO;
/** Obrigações manuais e recorrentes, sem cálculo fiscal nem efeito financeiro. */
final class OrganizationObligations
{
 private PDO $pdo;public function __construct(private readonly int $organizationId){if($organizationId<=0)throw new InvalidArgumentException('Empresa inválida.');$this->pdo=Connection::get();}
 public function create(array $data,int $userId,array $files=[]):array{$fields=$this->fields($data);$key=$this->key($data['idempotency_key']??null);OrganizationFiles::validate($files);$existing=$this->byKey($key);if($existing!==null)return['id'=>$existing,'duplicate'=>true,'count'=>1];$frequency=$fields['frequency'];$count=['once'=>1,'monthly'=>12,'quarterly'=>8,'yearly'=>5][$frequency];$months=['once'=>0,'monthly'=>1,'quarterly'=>3,'yearly'=>12][$frequency];$series=$count>1?bin2hex(random_bytes(16)):null;$stored=[];$this->pdo->beginTransaction();try{$first=0;for($i=0;$i<$count;$i++){$due=$this->plusMonths($fields['due_date'],$months*$i);$competence=$this->plusMonths($fields['competence_date'],$months*$i);$occurrenceKey=$i===0?$key:hash('sha256',$key.'-'.$i);$q=$this->pdo->prepare('INSERT INTO organization_obligations (organization_id,series_id,sequence_no,title,description,obligation_type,competence_date,due_date,responsible_user_id,frequency,amount_cents,notes,status,idempotency_key,created_by) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,\'pending\',?,?)');$q->execute([$this->organizationId,$series,$i+1,$fields['title'],$fields['description'],$fields['type'],$competence,$due,$fields['responsible_user_id'],$frequency,$fields['amount_cents'],$fields['notes'],$occurrenceKey,$userId]);$id=(int)$this->pdo->lastInsertId();$first=$first?:$id;$this->history($id,'created',$userId,['sequence'=>$i+1,'series_total'=>$count]);}foreach($files as$file){$saved=OrganizationFiles::store($this->organizationId,'obligations',$file);$stored[]=$saved['path'];$this->pdo->prepare('INSERT INTO organization_obligation_attachments (obligation_id,organization_id,uploaded_by,stored_path,original_name,mime_type,size_bytes) VALUES (?,?,?,?,?,?,?)')->execute([$first,$this->organizationId,$userId,$saved['path'],$saved['name'],$saved['mime'],$saved['size']]);}$this->pdo->commit();return['id'=>$first,'duplicate'=>false,'count'=>$count];}catch(\Throwable$e){if($this->pdo->inTransaction())$this->pdo->rollBack();foreach($stored as$path)OrganizationFiles::remove($this->organizationId,'obligations',$path);if($e instanceof \PDOException&&$e->getCode()==='23000'&&($id=$this->byKey($key))!==null)return['id'=>$id,'duplicate'=>true,'count'=>1];throw$e;}}
 public function update(int $id,array $data,int $userId,array $files=[]):void{$current=$this->find($id);if($current['status']==='cancelled')throw new InvalidArgumentException('Obrigação cancelada não pode ser editada.');$f=$this->fields($data);OrganizationFiles::validate($files);$this->pdo->beginTransaction();try{$this->pdo->prepare('UPDATE organization_obligations SET title=?,description=?,obligation_type=?,competence_date=?,due_date=?,responsible_user_id=?,amount_cents=?,notes=? WHERE id=? AND organization_id=?')->execute([$f['title'],$f['description'],$f['type'],$f['competence_date'],$f['due_date'],$f['responsible_user_id'],$f['amount_cents'],$f['notes'],$id,$this->organizationId]);foreach($files as$file){$saved=OrganizationFiles::store($this->organizationId,'obligations',$file);$this->pdo->prepare('INSERT INTO organization_obligation_attachments (obligation_id,organization_id,uploaded_by,stored_path,original_name,mime_type,size_bytes) VALUES (?,?,?,?,?,?,?)')->execute([$id,$this->organizationId,$userId,$saved['path'],$saved['name'],$saved['mime'],$saved['size']]);}$this->history($id,'updated',$userId);$this->pdo->commit();}catch(\Throwable$e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw$e;}}
 public function setStatus(int$id,string$status,int$userId):void{if(!in_array($status,['pending','completed','cancelled'],true))throw new InvalidArgumentException('Situação inválida.');$this->find($id);$q=$this->pdo->prepare('UPDATE organization_obligations SET status=?,completed_at=?,cancelled_at=? WHERE id=? AND organization_id=?');$q->execute([$status,$status==='completed'?date('Y-m-d H:i:s'):null,$status==='cancelled'?date('Y-m-d H:i:s'):null,$id,$this->organizationId]);$this->history($id,$status,$userId);}
 public function listing(array$filters=[]):array{$start=$this->date($filters['start']??date('Y-m-01'));$end=$this->date($filters['end']??date('Y-m-t',strtotime('+2 months')));if($end<$start)throw new InvalidArgumentException('Período inválido.');$where=['o.organization_id=?','o.due_date BETWEEN ? AND ?'];$args=[$this->organizationId,$start,$end];if(in_array($filters['status']??'', ['pending','completed','cancelled','overdue','upcoming'],true)){$status=$filters['status'];if($status==='overdue')$where[]="o.status='pending' AND o.due_date<CURDATE()";elseif($status==='upcoming')$where[]="o.status='pending' AND o.due_date BETWEEN CURDATE() AND DATE_ADD(CURDATE(),INTERVAL 7 DAY)";else{$where[]='o.status=?';$args[]=$status;}}if(($filters['type']??'')!==''){$where[]='o.obligation_type=?';$args[]=mb_substr((string)$filters['type'],0,60);}$q=$this->pdo->prepare('SELECT o.*,TRIM(CONCAT_WS(\' \',u.first_name,u.last_name)) responsible_name FROM organization_obligations o LEFT JOIN users u ON u.id=o.responsible_user_id WHERE '.implode(' AND ',$where).' ORDER BY o.due_date,o.id');$q->execute($args);$rows=$q->fetchAll(PDO::FETCH_ASSOC);$ind=['pending'=>0,'upcoming'=>0,'overdue'=>0,'completed'=>0];$today=date('Y-m-d');$soon=date('Y-m-d',strtotime('+7 days'));foreach($rows as&$row){$row['display_status']=$row['status']==='pending'?($row['due_date']<$today?'overdue':($row['due_date']<=$soon?'upcoming':'pending')):$row['status'];if(isset($ind[$row['display_status']]))$ind[$row['display_status']]++;$row['attachments']=$this->attachments((int)$row['id']);}return['rows'=>$rows,'indicators'=>$ind,'start'=>$start,'end'=>$end];}
 public function find(int$id):array{$q=$this->pdo->prepare('SELECT * FROM organization_obligations WHERE id=? AND organization_id=?');$q->execute([$id,$this->organizationId]);$row=$q->fetch(PDO::FETCH_ASSOC);if(!$row)throw new InvalidArgumentException('Obrigação não encontrada.');return$row;}
 public function attachment(int$id):?array{$q=$this->pdo->prepare('SELECT * FROM organization_obligation_attachments WHERE id=? AND organization_id=?');$q->execute([$id,$this->organizationId]);return$q->fetch(PDO::FETCH_ASSOC)?:null;}
 public function historyRows(int$id):array{$this->find($id);$q=$this->pdo->prepare('SELECT h.*,TRIM(CONCAT_WS(\' \',u.first_name,u.last_name)) actor_name FROM organization_obligation_history h LEFT JOIN users u ON u.id=h.actor_user_id WHERE h.obligation_id=? AND h.organization_id=? ORDER BY h.id DESC');$q->execute([$id,$this->organizationId]);return$q->fetchAll(PDO::FETCH_ASSOC);}
 private function attachments(int$id):array{$q=$this->pdo->prepare('SELECT id,original_name,size_bytes FROM organization_obligation_attachments WHERE obligation_id=? AND organization_id=? ORDER BY id');$q->execute([$id,$this->organizationId]);return$q->fetchAll(PDO::FETCH_ASSOC);}
 private function fields(array$d):array{$title=trim((string)($d['title']??''));if($title===''||mb_strlen($title)>180)throw new InvalidArgumentException('Informe o nome da obrigação.');$type=trim((string)($d['type']??'other'));if($type===''||mb_strlen($type)>60)throw new InvalidArgumentException('Informe o tipo.');$frequency=in_array($d['frequency']??'once',['once','monthly','quarterly','yearly'],true)?$d['frequency']:'once';$responsible=$this->responsible($d['responsible_user_id']??null);$amount=trim((string)($d['amount']??''));return['title'=>$title,'description'=>$this->text($d['description']??null,5000),'type'=>$type,'competence_date'=>$this->date($d['competence_date']??null),'due_date'=>$this->date($d['due_date']??null),'responsible_user_id'=>$responsible,'frequency'=>$frequency,'amount_cents'=>$amount===''?null:Finance::parseCents($amount),'notes'=>$this->text($d['notes']??null,5000)];}
 private function responsible(mixed$id):?int{if($id===null||$id==='')return null;$id=filter_var($id,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);$q=$this->pdo->prepare("SELECT m.user_id FROM organization_members m WHERE m.organization_id=? AND m.user_id=? AND m.status='active'");$q->execute([$this->organizationId,$id===false?0:$id]);if($id===false||$q->fetchColumn()===false)throw new InvalidArgumentException('Responsável inválido.');return(int)$id;}
 private function history(int$id,string$action,?int$user,array$meta=[]):void{$this->pdo->prepare('INSERT INTO organization_obligation_history (obligation_id,organization_id,actor_user_id,action,metadata_json) VALUES (?,?,?,?,?)')->execute([$id,$this->organizationId,$user,$action,$meta===[]?null:json_encode($meta,JSON_THROW_ON_ERROR)]);}
 private function byKey(string$key):?int{$q=$this->pdo->prepare('SELECT id FROM organization_obligations WHERE organization_id=? AND idempotency_key=?');$q->execute([$this->organizationId,$key]);$id=$q->fetchColumn();return$id===false?null:(int)$id;}
 private function key(mixed$v):string{$v=is_string($v)?trim($v):'';if(!preg_match('/^[a-f0-9]{32,64}$/',$v))throw new InvalidArgumentException('Solicitação inválida. Atualize a página.');return$v;}
 private function date(mixed$v):string{$d=is_string($v)?DateTimeImmutable::createFromFormat('!Y-m-d',$v):false;if(!$d||$d->format('Y-m-d')!==$v)throw new InvalidArgumentException('Data inválida.');return$v;}
 private function plusMonths(string$date,int$months):string{$d=new DateTimeImmutable($date);$first=$d->modify('first day of this month')->modify('+'.$months.' months');return$first->setDate((int)$first->format('Y'),(int)$first->format('n'),min((int)$d->format('j'),(int)$first->format('t')))->format('Y-m-d');}
 private function text(mixed$v,int$max):?string{$v=trim((string)$v);if($v==='')return null;if(mb_strlen($v)>$max)throw new InvalidArgumentException('Texto acima do limite.');return$v;}
}
